import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabaseClient';

export default function Register() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [confirma, setConfirma] = useState('');
  const [loading, setLoading] = useState(false);
  const [erro, setErro] = useState('');
  const [sucesso, setSucesso] = useState(false);

  const handleRegister = async () => {
    setErro('');
    if (senha !== confirma) { setErro('As senhas não coincidem.'); return; }
    if (senha.length < 6) { setErro('Senha deve ter no mínimo 6 caracteres.'); return; }
    setLoading(true);
    const { error } = await supabase.auth.signUp({ email, password: senha });
    if (error) setErro(error.message);
    else setSucesso(true);
    setLoading(false);
  };

  const styles = {
    page: {
      minHeight: '100vh',
      background: '#030108',
      color: 'white',
      fontFamily: 'sans-serif',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '30px',
      position: 'relative',
      overflow: 'hidden',
    },
    glow: {
      position: 'fixed',
      top: '-20vh', left: '-10vw',
      width: '70vw', height: '70vh',
      borderRadius: '50%',
      background: 'radial-gradient(ellipse, rgba(80,20,160,0.18) 0%, transparent 70%)',
      pointerEvents: 'none',
    },
    logo: {
      fontFamily: '"Palatino Linotype", Palatino, serif',
      fontSize: '1rem', letterSpacing: '6px',
      opacity: 0.4, marginBottom: '50px',
      cursor: 'pointer',
    },
    card: {
      background: 'rgba(255,255,255,0.02)',
      border: '1px solid rgba(255,255,255,0.07)',
      borderRadius: '24px',
      padding: '44px',
      width: '100%',
      maxWidth: '400px',
      backdropFilter: 'blur(20px)',
    },
    title: {
      fontFamily: '"Palatino Linotype", Palatino, serif',
      fontSize: '1.6rem', fontWeight: '400',
      marginBottom: '8px',
    },
    subtitle: {
      fontSize: '0.85rem',
      color: 'rgba(255,255,255,0.3)',
      marginBottom: '36px',
      lineHeight: 1.6,
    },
    label: {
      fontSize: '0.7rem',
      color: 'rgba(255,255,255,0.3)',
      letterSpacing: '2px',
      textTransform: 'uppercase',
      marginBottom: '8px',
      display: 'block',
    },
    input: {
      width: '100%',
      padding: '13px 18px',
      background: 'rgba(255,255,255,0.04)',
      border: '1px solid rgba(255,255,255,0.08)',
      borderRadius: '12px',
      color: 'white',
      fontSize: '0.95rem',
      marginBottom: '22px',
      boxSizing: 'border-box',
      outline: 'none',
      fontFamily: 'sans-serif',
      transition: 'border-color 0.3s',
    },
    btn: {
      width: '100%',
      padding: '15px',
      background: 'linear-gradient(135deg, rgba(124,58,237,0.9), rgba(79,70,229,0.9))',
      border: '1px solid rgba(192,132,252,0.3)',
      borderRadius: '12px',
      color: 'white',
      fontSize: '0.85rem',
      cursor: 'pointer',
      letterSpacing: '2px',
      boxShadow: '0 0 40px rgba(124,58,237,0.2)',
      marginTop: '4px',
    },
    erro: {
      fontSize: '0.82rem',
      color: '#f87171',
      marginBottom: '16px',
      textAlign: 'center',
      lineHeight: 1.5,
    },
    link: {
      textAlign: 'center',
      marginTop: '24px',
      fontSize: '0.82rem',
      color: 'rgba(255,255,255,0.25)',
    },
    linkBtn: {
      background: 'none',
      border: 'none',
      color: 'rgba(192,132,252,0.7)',
      cursor: 'pointer',
      fontSize: '0.82rem',
      letterSpacing: '0.5px',
      padding: '0 4px',
    },
    sucesso: {
      textAlign: 'center',
      padding: '20px 0',
    },
    sucessoIcon: {
      fontSize: '3rem',
      marginBottom: '20px',
      display: 'block',
    },
    sucessoTitle: {
      fontFamily: '"Palatino Linotype", Palatino, serif',
      fontSize: '1.4rem',
      fontWeight: '400',
      marginBottom: '12px',
    },
    sucessoText: {
      fontSize: '0.88rem',
      color: 'rgba(255,255,255,0.35)',
      lineHeight: 1.8,
    },
  };

  return (
    <div style={styles.page}>
      <div style={styles.glow} />
      <div style={{ position: 'fixed', bottom: '-20vh', right: '-10vw', width: '60vw', height: '60vh', borderRadius: '50%', background: 'radial-gradient(ellipse, rgba(20,50,140,0.12) 0%, transparent 70%)', pointerEvents: 'none' }} />

      <p style={styles.logo} onClick={() => navigate('/')}>EVERLY</p>

      <div style={styles.card}>
        {sucesso ? (
          <div style={styles.sucesso}>
            <span style={styles.sucessoIcon}>✦</span>
            <h2 style={styles.sucessoTitle}>Conta criada</h2>
            <p style={styles.sucessoText}>
              Verifique seu email para confirmar sua conta e começar sua jornada.
            </p>
            <button onClick={() => navigate('/login')} style={{ ...styles.btn, marginTop: '30px' }}>
              IR PARA O LOGIN
            </button>
          </div>
        ) : (
          <>
            <h1 style={styles.title}>Criar conta</h1>
            <p style={styles.subtitle}>Comece a preservar sua história hoje.</p>

            <label style={styles.label}>Email</label>
            <input
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="seu@email.com"
              style={styles.input}
              onFocus={e => e.target.style.borderColor = 'rgba(124,58,237,0.5)'}
              onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.08)'}
            />

            <label style={styles.label}>Senha</label>
            <input
              type="password"
              value={senha}
              onChange={e => setSenha(e.target.value)}
              placeholder="••••••••"
              style={styles.input}
              onFocus={e => e.target.style.borderColor = 'rgba(124,58,237,0.5)'}
              onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.08)'}
            />

            <label style={styles.label}>Confirmar senha</label>
            <input
              type="password"
              value={confirma}
              onChange={e => setConfirma(e.target.value)}
              placeholder="••••••••"
              style={styles.input}
              onFocus={e => e.target.style.borderColor = 'rgba(124,58,237,0.5)'}
              onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.08)'}
              onKeyPress={e => e.key === 'Enter' && handleRegister()}
            />

            {erro && <p style={styles.erro}>{erro}</p>}

            <button style={styles.btn} onClick={handleRegister} disabled={loading}>
              {loading ? 'Criando conta...' : 'CRIAR CONTA'}
            </button>

            <p style={styles.link}>
              Já tem uma conta?
              <button style={styles.linkBtn} onClick={() => navigate('/login')}>Entrar</button>
            </p>
          </>
        )}
      </div>
    </div>
  );
}
